import { Component, createMemo, For, Show } from "solid-js";

import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { TooltipKeyword } from "#core/ui-next/components/tooltip-keyword.jsx";
import { TooltipHorizontalPosition, TooltipVerticalPosition } from "#core/ui-next/components/tooltip.jsx";

import { PlotTooltipConstructibleInfo } from "#base/ui-next/tooltips/plot-tooltip/helpers.js";
import { ProductionTooltip } from "#base/ui-next/tooltips/production-tooltip.jsx";

interface UniqueQuarterSectionProps {
	definition: UniqueQuarterDefinition;
	buildings: PlotTooltipConstructibleInfo[];
}

/**
 * Renders a unique quarter as a header (hex icon, name, description) followed by
 * its constituent buildings connected by a vertical timeline rail with circle markers.
 */
export const UniqueQuarterSection: Component<UniqueQuarterSectionProps> = (props) => {
	const hasBuildings = () => props.buildings.length > 0;
	return (
		<div class="flex flex-col w-full">
			{/* Header: hex icon + title/label/description, with a half-line that descends into the rail. */}
			<div class="flex flex-row items-stretch">
				<div class="w-12 shrink-0 flex justify-center items-start">
					<Icon
						class="size-6 pt-1"
						name="CITY_UNIQUE_QUARTER"
					/>
				</div>
				<div class="w-4 shrink-0 flex flex-col items-center">
					<Show when={hasBuildings()}>
						<div
							class="w-px flex-1"
							style={{ "background-color": "#B79A64" }}
						/>
					</Show>
				</div>
				<div class="flex flex-col flex-auto ml-1">
					<L10n.Stylize
						class="font-title text-sm uppercase text-accent-1"
						text={props.definition.Name}
					/>
					<L10n.Stylize
						class="font-body text-sm text-secondary"
						text="LOC_PLOT_TOOLTIP_UNIQUE_QUARTER"
					/>
					<L10n.Stylize
						class="font-body text-sm text-accent-3 mt-1"
						text={props.definition.Description}
					/>
				</div>
			</div>

			{/* Building rows: building icon | rail (line + circle marker) | name */}
			<For each={props.buildings}>
				{(building, index) => {
					const isLast = createMemo(() => index() === props.buildings.length - 1);
					return (
						<div
							class="flex flex-row items-center"
							style={{
								background: "linear-gradient(90deg, #36383F 5.59%, rgba(54, 56, 63, 0.00) 99.99%)",
							}}
						>
							<div class="w-12 shrink-0 flex justify-center">
								<Icon
									class="size-7 py-0\.5"
									isUrl
									name={building.icon}
								/>
							</div>
							<div class="w-4 shrink-0 self-stretch flex flex-col items-center">
								<div
									class="w-px flex-1"
									style={{ "background-color": "#B79A64" }}
								/>
								<div
									// flip if this is the last building
									style={{
										transform: isLast() ? "rotate(180deg)" : "none",
									}}
								>
									<Icon
										class="size-3 shrink-0"
										isUrl
										name="url(blp:tooltip_uniqueIcon)"
									/>
								</div>
								<div
									class="w-px flex-1"
									style={{ "background-color": "#B79A64" }}
								/>
							</div>
							<div class="flex flex-col flex-1 ml-1 justify-center">
								<Show
									when={building.isBuilding || building.isWonder}
									fallback={
										<L10n.Stylize
											class="font-title text-sm"
											text={building.title}
										/>
									}
								>
									<ProductionTooltip
										type={building.type}
										name={building.title}
										initialVPosition={TooltipVerticalPosition.BOTTOM}
										initialHPosition={TooltipHorizontalPosition.RIGHT}
									>
										<TooltipKeyword>
											<L10n.Stylize
												class="font-title text-sm"
												text={building.title}
											/>
										</TooltipKeyword>
									</ProductionTooltip>
								</Show>
								<Show when={building.damaged}>
									<div class="flex items-center">
										<Icon
											class="size-5"
											isUrl
											name="url(blp:fonticon_damaged)"
										/>
									</div>
								</Show>
							</div>
						</div>
					);
				}}
			</For>
		</div>
	);
};
